import csv
rows=[]
with open('enc_tagalign_meta.tsv') as f:
 r=csv.DictReader(f,delimiter='\\t')
 for x in r:
  size=x['file_size']; 
  if size:
   size=int(size)
   if x['assembly'] in ['GRCh38','hg38'] or 'GRCh38' in str(x['assembly']):
    rows.append((abs(size-321498264),size,x['accession'],x['targets'],x['dataset'],x['assembly'],x['read_length'],x['biosample']))
print('GRCh38 rows',len(rows))
for row in sorted(rows)[:30]: print(row)
