import requests
url='https://www.encodeproject.org/search/'
for ds in ['/experiments/ENCSR100PNV/','/experiments/ENCSR832JVP/','/experiments/ENCSR956CTX/','/experiments/ENCSR800IIW/']:
 params={'type':'File','dataset':ds,'file_format':'tagAlign','limit':'all','format':'json',
