 j=requests.get(url,params=params,headers={'Accept':'application/json'}).json()
 print('\\n',ds, 'total',j.get('total'))
 for x in j.get('@graph',[]): print(x.get('accession'),x.get('file_size'),x.get('target'),x.get('assembly'),x.get('biological_replicates'),x.get('technical_replicates'),x.get('href'))
PY"

